  [1311591] = { "Attivato da ⟦Holy Shock=Folgore Sacra⟧. Cura il bersaglio e il suo gruppo di $N1. I membri del gruppo devono trovarsi entro $N2 m dal bersaglio.", nil, 0x1eea785c, nil, "um" },
